}

fn to_decimal(roman_number: &str) -> i32 {

	let mut num = 0;

	for c in roman_number.chars() {
		num += roman_char_to_decimal(c);
	}

	num
}

fn roman_char_to_decimal(roman_char: char) -> i32 {

	match roman_char {
	    'I' => 1,
	    'V' => 5,
	    'X' => 10,
	    'L' => 50,
	    'C' => 100,
	    'D' => 500,
	    'M' => 1000,
	    _ => 0,
	}
}

